from __future__ import annotations

import base64
import csv
import io
import os
from typing import Any

import psycopg2
from psycopg2.extras import RealDictCursor
from nicegui import ui

# Configure DATABASE_URL no Render. A senha não fica gravada no código.
DATABASE_URL = os.getenv("DATABASE_URL") or os.getenv("NEON_DATABASE_URL")
if not DATABASE_URL:
    raise RuntimeError("Configure DATABASE_URL nas variáveis de ambiente do Render.")

PORT = int(os.getenv("PORT", "8080"))
TABLE_NAME = "processos_mp"

# Base anexada incorporada no próprio arquivo para facilitar o deploy.
EMBEDDED_TSV = base64.b64decode(
    ""
).decode("utf-8-sig")


def get_connection():
    return psycopg2.connect(DATABASE_URL)


def initialize_database() -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {TABLE_NAME} (
                    id BIGSERIAL PRIMARY KEY,
                    pasta TEXT NOT NULL DEFAULT '',
                    numero_processo TEXT NOT NULL DEFAULT '',
                    procedimento TEXT NOT NULL DEFAULT '',
                    link TEXT NOT NULL DEFAULT ''
                )
                """
            )
            cursor.execute(f"SELECT COUNT(*) FROM {TABLE_NAME}")
            total = cursor.fetchone()[0]
            if total == 0:
                import_embedded_data(connection)
        connection.commit()


def import_embedded_data(connection) -> int:
    inserted = 0
    reader = csv.reader(io.StringIO(EMBEDDED_TSV), delimiter="\t", quotechar='"')
    next(reader, None)  # cabeçalho
    with connection.cursor() as cursor:
        for row in reader:
            if not row or not any(cell.strip() for cell in row):
                continue
            values = (row + [""] * 4)[:4]
            cursor.execute(
                f"INSERT INTO {TABLE_NAME} (pasta, numero_processo, procedimento, link) VALUES (%s, %s, %s, %s)",
                tuple(value.strip() for value in values),
            )
            inserted += 1
    connection.commit()
    return inserted


def list_processes(search: str = "") -> list[dict[str, Any]]:
    with get_connection() as connection:
        with connection.cursor(cursor_factory=RealDictCursor) as cursor:
            if search.strip():
                pattern = f"%{search.strip()}%"
                cursor.execute(
                    f"""
                    SELECT id, pasta, numero_processo, procedimento, link
                    FROM {TABLE_NAME}
                    WHERE pasta ILIKE %s
                       OR numero_processo ILIKE %s
                       OR procedimento ILIKE %s
                       OR link ILIKE %s
                    ORDER BY id
                    """,
                    (pattern, pattern, pattern, pattern),
                )
            else:
                cursor.execute(
                    f"SELECT id, pasta, numero_processo, procedimento, link FROM {TABLE_NAME} ORDER BY id"
                )
            return [dict(row) for row in cursor.fetchall()]


def save_process(data: dict[str, str], process_id: int | None = None) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if process_id is None:
                cursor.execute(
                    f"INSERT INTO {TABLE_NAME} (pasta, numero_processo, procedimento, link) VALUES (%s, %s, %s, %s)",
                    (data["pasta"], data["numero_processo"], data["procedimento"], data["link"]),
                )
            else:
                cursor.execute(
                    f"""
                    UPDATE {TABLE_NAME}
                    SET pasta = %s, numero_processo = %s, procedimento = %s, link = %s
                    WHERE id = %s
                    """,
                    (data["pasta"], data["numero_processo"], data["procedimento"], data["link"], process_id),
                )
        connection.commit()


def delete_process(process_id: int) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(f"DELETE FROM {TABLE_NAME} WHERE id = %s", (process_id,))
        connection.commit()


initialize_database()

COLUMNS = [
    {"name": "pasta", "label": "Pasta", "field": "pasta", "align": "left", "sortable": True},
    {"name": "numero_processo", "label": "Nº Processo", "field": "numero_processo", "align": "left"},
    {"name": "procedimento", "label": "Procedimento", "field": "procedimento", "align": "left"},
    {"name": "link", "label": "Pasta do MP Drive", "field": "link", "align": "left"},
]


@ui.page("/")
def main_page() -> None:
    search_input: ui.input
    process_table: ui.table
    dialog: ui.dialog
    total_label: ui.label
    fields: dict[str, Any] = {}
    current_id: int | None = None

    def refresh_table() -> None:
        process_table.rows = list_processes(search_input.value or "")
        process_table.update()
        total_label.set_text(f"{len(process_table.rows)} processo(s) exibido(s)")

    def close_dialog() -> None:
        dialog.close()

    def open_form(process: dict[str, Any] | None = None) -> None:
        nonlocal current_id
        current_id = process["id"] if process else None
        dialog.clear()
        with dialog, ui.card().classes("w-full max-w-4xl"):
            ui.label("Editar processo do Ministério Público" if process else "Adicionar processo").classes("text-h5")
            ui.label("Preencha os dados do procedimento e o link da pasta digitalizada.").classes("text-gray-600 mb-3")
            with ui.column().classes("w-full gap-2"):
                fields["pasta"] = ui.input("Pasta", value=str(process.get("pasta", "") if process else "")).props("outlined dense")
                fields["numero_processo"] = ui.textarea("Nº Processo", value=str(process.get("numero_processo", "") if process else "")).props("outlined autogrow")
                fields["procedimento"] = ui.textarea("Procedimento", value=str(process.get("procedimento", "") if process else "")).props("outlined autogrow")
                fields["link"] = ui.input("Pasta do MP Drive", value=str(process.get("link", "") if process else "")).props("outlined dense")
            with ui.row().classes("w-full justify-between mt-4"):
                if process:
                    ui.button("Excluir", icon="delete", color="negative", on_click=confirm_delete).props("outline")
                else:
                    ui.element("div")
                with ui.row().classes("gap-2"):
                    ui.button("Cancelar", on_click=close_dialog).props("flat")
                    ui.button("Salvar", icon="save", color="primary", on_click=save_form)
        dialog.open()

    def save_form() -> None:
        data = {key: str(field.value or "").strip() for key, field in fields.items()}
        if not data["procedimento"] and not data["numero_processo"]:
            ui.notify("Informe o número do processo ou o procedimento.", type="warning")
            return
        save_process(data, current_id)
        close_dialog()
        refresh_table()
        ui.notify("Processo salvo com sucesso.", type="positive")

    def confirm_delete() -> None:
        if current_id is None:
            return
        with ui.dialog() as confirmation:
            with ui.card().classes("w-96"):
                ui.label("Excluir processo?").classes("text-h6")
                ui.label("Esta ação não poderá ser desfeita.").classes("text-gray-600")
                with ui.row().classes("w-full justify-end gap-2 mt-4"):
                    ui.button("Cancelar", on_click=confirmation.close).props("flat")
                    def do_delete() -> None:
                        delete_process(current_id)
                        confirmation.close()
                        close_dialog()
                        refresh_table()
                        ui.notify("Processo excluído.", type="positive")
                    ui.button("Excluir", color="negative", on_click=do_delete)
        confirmation.open()

    def handle_double_click(event: Any) -> None:
        args = event.args
        row = None
        if isinstance(args, dict):
            row = args.get("row") or args
        elif isinstance(args, list):
            for item in args:
                if isinstance(item, dict) and ("id" in item or "row" in item):
                    row = item.get("row", item)
                    break
        if row and row.get("id") is not None:
            process = next((item for item in process_table.rows if item["id"] == row["id"]), None)
            if process:
                open_form(process)

    ui.add_head_html("""
        <style>
            body { background: #f5f7fb; }
            .q-table th { font-weight: 700; background: #e8eef7; }
            .q-table tbody tr { cursor: pointer; }
            .q-table tbody tr:hover { background: #eaf2ff !important; }
        </style>
    """)

    with ui.header().classes("items-center justify-between bg-indigo-950 px-6"):
        with ui.row().classes("items-center gap-3"):
            ui.icon("account_balance", size="32px").classes("text-indigo-200")
            ui.label("Ministério Público").classes("text-h5 text-white font-bold")
        ui.label("Cadastro de procedimentos e inquéritos").classes("text-indigo-100")

    with ui.column().classes("w-full max-w-screen-2xl mx-auto p-6 gap-4"):
        with ui.card().classes("w-full"):
            with ui.row().classes("w-full items-end gap-3"):
                search_input = ui.input("Buscar por pasta, número, procedimento ou link").props("outlined clearable").classes("flex-1")
                ui.button("Buscar", icon="search", on_click=refresh_table).classes("h-14")
                ui.button("Adicionar processo", icon="add", color="primary", on_click=lambda: open_form()).classes("h-14")
            search_input.on("keydown.enter", refresh_table)

        with ui.row().classes("w-full items-center justify-between"):
            total_label = ui.label()
            ui.label("Dica: dê duplo clique em uma linha para editar ou excluir.").classes("text-gray-600")

        process_table = ui.table(
            columns=COLUMNS,
            rows=list_processes(),
            row_key="id",
            pagination={"rowsPerPage": 25},
        ).classes("w-full")
        process_table.add_slot(
            "body-cell-link",
            """
            <q-td :props="props">
                <a v-if="props.value" :href="props.value" target="_blank" rel="noopener" class="text-indigo-700 underline">Abrir pasta</a>
                <span v-else class="text-gray-400">Sem link</span>
            </q-td>
            """,
        )
        process_table.on("rowDblclick", handle_double_click)
        total_label.set_text(f"{len(process_table.rows)} processo(s) exibido(s)")

    dialog = ui.dialog()


ui.run(title="Ministério Público", host="0.0.0.0", port=PORT, reload=False)
